def _fill_period(values, period):
    phase = {}
    for index, color in values:
        key = index % period
        if key in phase and phase[key] != color:
            return None
        phase[key] = color
    if not phase:
        return None
    for k in range(period):
        if k not in phase:
            d = next(d for d in range(1, period + 1) if (k-d) % period in phase)
            phase[k] = phase[(k-d) % period]
    return phase

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]
    # Uniform horizontal stripes sampled at selected rows.
    if all(len(set(row)) <= 1 for row in grid):
        samples = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        for period in range(1, h + 1):
            phase = _fill_period(samples, period)
            if phase is not None:
                return [[phase[r % period] for _ in range(w)] for r in range(h)]
    # Repeating color bands along anti-diagonals (constant r+c).
    samples = [(r+c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    for period in range(1, h + w):
        phase = _fill_period(samples, period)
        if phase is not None:
            return [[phase[(r+c) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]

